input.script:
export const meta = {
  name: 'data-lake-full-gap-map',
  description: 'Exhaustive map of every data family in bolt-v2: producer, store, durability, consumers, gaps — multi-modal sweep, per-family trace, adversarial verify, completeness critique, consolidated gap registry',
  phases: [
    { title: 'Sweep', detail: '6 parallel discovery angles (writers, readers, config, S3, issues, runtime)', model: 'opus' },
    { title: 'Register', detail: 'merge sweeps into canonical MECE data-family list', model: 'opus' },
    { title: 'Trace', detail: 'end-to-end trace per data family', model: 'opus' },
    { title: 'Verify', detail: 'adversarial verification per family (hunt hidden consumers/durability)', model: 'opus' },
    { title: 'Critique', detail: 'coverage + depth critics attack the map', model: 'opus' },
    { title: 'Supplement', detail: 'trace+verify families the critics found missing', model: 'opus' },
    { title: 'Consolidate', detail: 'typed gap registry + ownership + residual unknowns', model: 'opus' },
  ],
}

const HAZARDS = [
  'Repo: /Users/spson/Projects/Claude/bolt-v2 — Rust trading system on NautilusTrader (NT), NT pinned rev 6be5a5094716790a8ca2875445fde4fa2586107e. Anchor code reads at origin/main (use git show origin/main:<path> or git grep <pattern> origin/main -- <path>) because the local checkout carries unrelated in-flight commits.',
  'READ-ONLY: never edit files, never run cargo build/test/clippy, never use LSP tools.',
  'Allowed tools: git log/show/grep, Read/Grep tools, gh CLI (auto-resolves remote), and aws CLI STRICTLY read-only (sts get-caller-identity, s3 ls, s3api list-*/head-*). NEVER aws s3 cp/rm/sync/mb, never SSM commands of any kind — remote-instance access is gated; mark on-box state as UNVERIFIABLE-from-repo / manual-check instead.',
  'Anchor every claim on symbol/function/config-key names plus file paths, not line numbers. Every claim needs the command you ran plus a short output excerpt.',
  'Work FAST and bounded: hard cap around 4 minutes of tool calls; return partial results with explicit unknowns rather than running long.',
  'Today is 2026-07-03.',
].join('\n')

const SEED = [
  'PRIOR-SESSION HINTS (claims from earlier audits — use as leads, verify anything you rely on):',
  '- S3 bucket s3://bolt-parquet: ~567GB raw bought archives under a backfill-staging prefix (Polymarket tick L2+trades from a free R2 archive covering roughly Apr20-May25; venue L2 fidelity: full-L2 for Polymarket+OKX, snapshot-only for Hyperliquid/Deribit). Only the Polymarket NT-catalog conversion was called durable. A source-universe conversion campaign existed: Binance spot done, Bybit was running as of late June.',
  '- Live node writers known so far: src/nt_runtime_capture.rs -> src/lake_batch.rs (stream_to_lake binary) for market-data capture (7 NormalizedTable variants); src/bolt_v3_decision_evidence.rs appends order-intents.jsonl (BOLT_V3_DECISION_EVIDENCE_SCHEMA_VERSION=14, record-kind count growing per #219/#891); portfolio snapshots landed via #409; a durable realized-loss (kill-switch) accumulator landed via #673/#738; shadow settlement JSONL is a manual input to src/shadow_pnl.rs / shadow_pnl_report.',
  '- config/root.toml: catalog_fs_protocol="file", rotation_kind="none", required_catalog_prefix + LOCAL_PATH_URI_MARKER guard in lake_batch.rs = the local-only blockers; root Cargo.toml nautilus-persistence lacks the cloud feature (backtester crate has it).',
  '- Backtester: BacktestResultContract v2 JSON per run; crates/backtesting-vertical-slice/src/research_analytics.rs has run_backtest_sweep + build_run_pointer_index + validate_run_pointer_artifact_root (s3-enforcing) with NO non-test caller.',
  '- Research scripts: scripts/leadlag_*.py (duckdb/polars) read s3://bolt-parquet/backfill-staging directly.',
  '- Known data-gap issues: #77 durable trade history (P1), #36 settlement/redemption realized P&L, #763 rotate/archive decision evidence to S3 (P0), #724 calibration scoreboard, #219 evidence record kinds, #562 finish/verify NT-catalog conversion + decommission box, #568 python research on converted catalogs, #836 index/mark/funding raw data acquisition, #919/#920 evidence schema, #931 operator observability umbrella, #437 NT-first epic. Ledger comment on closed #1179: Lane 0 feeds complete; exit-side evidence has NO observed-input channel; max_event_receive_lag_ms config key deleted (next deploy boot-breaking by design).',
  '- Forward-capture families believed NEVER started: liquidations, IV/greeks, long/short ratio. Chainlink Data Streams is the settlement/resolution anchor (creds in SSM). A Deribit full-history TRADE scraper tool exists from a prior session.',
  '- Boxes: eu-west-1 terminated; eu-west-2 port complete but box believed INACTIVE; prior memory says no active deploy, but a live trade incident happened 2026-07-02, so deploy state is uncertain — treat on-box reality as manual-check.',
].join('\n')

const SWEEP_SCHEMA = {
  type: 'object',
  required: ['angle', 'findings', 'notes'],
  properties: {
    angle: { type: 'string' },
    findings: { type: 'array', items: { type: 'object', required: ['item', 'kind', 'evidence'], properties: { item: { type: 'string' }, kind: { type: 'string' }, evidence: { type: 'string' } } } },
    notes: { type: 'string' },
  },
}

const REGISTRY_SCHEMA = {
  type: 'object',
  required: ['families', 'excluded'],
  properties: {
    families: { type: 'array', items: { type: 'object', required: ['key', 'name', 'what', 'seed_pointers', 'priority'], properties: { key: { type: 'string' }, name: { type: 'string' }, what: { type: 'string' }, seed_pointers: { type: 'array', items: { type: 'string' } }, priority: { type: 'integer' } } } },
    excluded: { type: 'array', items: { type: 'object', required: ['name', 'why'], properties: { name: { type: 'string' }, why: { type: 'string' } } } },
  },
}

const TRACE_SCHEMA = {
  type: 'object',
  required: ['family_key', 'produced_by', 'stores', 'consumers', 'coverage_window', 'gaps', 'claims', 'unknowns'],
  properties: {
    family_key: { type: 'string' },
    produced_by: { type: 'string' },
    transport: { type: 'string' },
    stores: { type: 'array', items: { type: 'object', required: ['location', 'durability'], properties: { location: { type: 'string' }, durability: { type: 'string' } } } },
    consumers: { type: 'array', items: { type: 'string' } },
    coverage_window: { type: 'string' },
    schema_notes: { type: 'string' },
    gaps: { type: 'array', items: { type: 'object', required: ['gap', 'type'], properties: { gap: { type: 'string' }, type: { type: 'string' }, severity_hint: { type: 'string' } } } },
    claims: { type: 'array', items: { type: 'object', required: ['claim', 'evidence'], properties: { claim: { type: 'string' }, evidence: { type: 'string' } } } },
    unknowns: { type: 'array', items: { type: 'string' } },
  },
}

const VERIFY_SCHEMA = {
  type: 'object',
  required: ['family_key', 'verdicts', 'corrections'],
  properties: {
    family_key: { type: 'string' },
    verdicts: { type: 'array', items: { type: 'object', required: ['claim', 'verdict', 'evidence'], properties: { claim: { type: 'string' }, verdict: { type: 'string', enum: ['CONFIRMED', 'REFUTED', 'UNVERIFIABLE'] }, evidence: { type: 'string' } } } },
    corrections: { type: 'array', items: { type: 'string' } },
    hidden_consumers_found: { type: 'array', items: { type: 'string' } },
    hidden_durability_found: { type: 'array', items: { type: 'string' } },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['missing_families', 'weak_spots', 'notes'],
  properties: {
    missing_families: { type: 'array', items: { type: 'object', required: ['name', 'why', 'seed_pointers'], properties: { name: { type: 'string' }, why: { type: 'string' }, seed_pointers: { type: 'array', items: { type: 'string' } } } } },
    weak_spots: { type: 'array', items: { type: 'object', required: ['family_key', 'hole'], properties: { family_key: { type: 'string' }, hole: { type: 'string' } } } },
    notes: { type: 'string' },
  },
}

const CONSOLIDATED_SCHEMA = {
  type: 'object',
  required: ['gap_registry', 'unowned_gaps', 'residual_unknowns', 'map_summary'],
  properties: {
    gap_registry: { type: 'array', items: { type: 'object', required: ['id', 'family', 'gap', 'type', 'severity', 'blocks_what', 'owner_issue', 'evidence'], properties: { id: { type: 'string' }, family: { type: 'string' }, gap: { type: 'string' }, type: { type: 'string' }, severity: { type: 'string' }, blocks_what: { type: 'string' }, owner_issue: { type: 'string' }, evidence: { type: 'string' } } } },
    unowned_gaps: { type: 'array', items: { type: 'string' } },
    residual_unknowns: { type: 'array', items: { type: 'object', required: ['what', 'how_to_check'], properties: { what: { type: 'string' }, how_to_check: { type: 'string' } } } },
    map_summary: { type: 'string' },
  },
}

const SWEEPS = [
  {
    key: 'writers',
    brief: 'Find EVERY place code writes persistent data. In src/, crates/, scripts/: git grep origin/main for writer signatures — File::create, OpenOptions, write_all, append, serde_json::to_writer, BufWriter, ParquetDataCatalog, object_store, put, csv/feather/parquet writers, .jsonl and .parquet and .json path literals, std::fs::write, to_parquet, write_parquet, open(..., "w"|"a") in python. For each distinct written artifact: what binary/script writes it, what data it holds, where it lands (path/prefix). Cover the main live binary, every src/bin/*, every crates/backtesting-vertical-slice/src/bin/*, and every scripts/*.py that writes. kind=producer.',
  },
  {
    key: 'readers',
    brief: 'Find EVERY place code READS persisted data. git grep origin/main in src/, crates/, scripts/, tests/, justfile, .github/workflows, *.mjs, *.html for reader signatures — read_parquet, scan_parquet, duckdb, polars, read_to_string, File::open, from_reader, load, catalog reads, JSONL parsing, fixture directories, S3 GETs. For each reader: what it reads (path/family), which tool/binary/test it is, and whether it is production, research, viewer, or test-only. kind=consumer.',
  },
  {
    key: 'config-paths',
    brief: 'Enumerate every storage location the system knows about. Read config/root.toml fully at origin/main and list EVERY key naming a path, directory, bucket, prefix, rotation, protocol, or retention. Then git grep origin/main for "s3://" everywhere, for catalog_directory / _path / _dir / _root / prefix config keys in src/ and crates/, and any other config files (config/*.toml, *.yaml). Output one finding per distinct storage location/config key with what points at it. kind=store.',
  },
  {
    key: 's3-inventory',
    brief: 'Inventory ACTUAL cloud storage. First: aws sts get-caller-identity — if it fails, report blocked and return. Then: aws s3 ls (all buckets, note every bucket name). Then aws s3 ls s3://bolt-parquet/ (top-level prefixes, non-recursive). Then for up to 6 of the most important prefixes (catalogs, backfill-staging, anything evidence/decision/results-like): one bounded listing each — prefer one more non-recursive level; use --recursive --summarize ONLY on prefixes that look small, and cap total aws runtime under 2 minutes. Also check any other buckets that look bolt-related (one top-level ls each). For each prefix: rough size/object count if cheaply available, what the data appears to be, last-modified recency of a sample object. kind=store. If a listing is too large to summarize cheaply, say so explicitly rather than guessing.',
  },
  {
    key: 'issue-graph',
    brief: 'Map which GitHub issues OWN which data gaps. View these known issues: 77, 36, 219, 562, 568, 724, 763, 836, 919, 920, 931, 437 — for each: state, title, one-line scope of the data gap it owns, updatedAt. Then search for others: gh issue list --state open --limit 50 -S "<term>" --json number,title for terms: catalog, parquet, S3, archive, capture, settlement, evidence, calibration, conversion, retention, backfill, lake. Dedupe. Also fetch the owner ledger comment on issue 1179 and extract any data/feed follow-up items still open (especially the exit-side observed-input gap). kind=issue. One finding per issue: item=issue number+title, evidence=state+scope.',
  },
  {
    key: 'runtime',
    brief: 'Establish HOW data-writing processes actually run in production, from the repo only. Find: how stream_to_lake and the live node are launched (git grep origin/main for stream_to_lake, deploy scripts, .github/workflows deploy jobs, SSM document templates, systemd/launchd/cron/timer files, justfile targets); what order_execution_mode / shadow-mode config exists (can the same binary run capture-only?); any rotation/upload/sync jobs anywhere (cron, workflow schedules, scripts). Also: what deploy-state signals exist in-repo (target registries, instance configs) — do NOT attempt SSM/AWS instance calls; where on-box truth matters, output it as an unknown needing manual check. kind=runtime.',
  },
]

phase('Sweep')
log('6 parallel opus discovery sweeps: writers, readers, config paths, S3 reality, issue graph, runtime')
const sweepResults = await parallel(
  SWEEPS.map((s) => () =>
    agent(
      [HAZARDS, '', SEED, '', 'You are one discovery angle of a multi-modal sweep building a COMPLETE data map of this system. Other agents cover other angles; you are blind to them — go deep on yours and report everything you find, even if it seems minor. Set angle to: ' + s.key, '', 'YOUR ANGLE:', s.brief].join('\n'),
      { label: 'sweep:' + s.key, phase: 'Sweep', model: 'opus', effort: 'medium', schema: SWEEP_SCHEMA }
    )
  )
)
const sweeps = sweepResults.filter(Boolean)
const sweepsJson = JSON.stringify(sweeps)
log('Sweeps done: ' + sweeps.map((s) => s.angle).join(', '))

phase('Register')
const registry = await agent(
  [
    HAZARDS,
    '',
    SEED,
    '',
    'You are the REGISTRAR. Merge the six sweep outputs below into ONE canonical MECE list of data families for end-to-end tracing. Rules: (1) group micro-artifacts into coherent families (e.g. all 7 live NT capture tables = one family; all decision-evidence record kinds = one family) — target 10-16 families, never more than 16; (2) data families that SHOULD exist but have zero code today (never-captured feeds like liquidations/IV-greeks/long-short, exit-side observed inputs, settlement-outcome records) are FIRST-CLASS entries — include them; (3) every family gets seed_pointers: the file paths / symbols / S3 prefixes / issue numbers from the sweeps that a tracer should start from; (4) priority 1 = most decision-relevant to proving the edge, seeing the bot, or scaling; (5) list what you deliberately excluded (build caches, CI plumbing artifacts, logs that are pure debugging) with why. Do not run tools except quick sanity greps; your job is synthesis.',
    '',
    'SWEEP OUTPUTS (JSON):',
    sweepsJson,
  ].join('\n'),
  { label: 'registrar', phase: 'Register', model: 'opus', effort: 'high', schema: REGISTRY_SCHEMA }
)

let families = (registry && registry.families ? registry.families : []).slice()
families.sort((a, b) => (a.priority || 9) - (b.priority || 9))
if (families.length > 16) {
  log('Registrar returned ' + families.length + ' families; tracing top 16 by priority, dropping: ' + families.slice(16).map((f) => f.key).join(', '))
  families = families.slice(0, 16)
}
log('Canonical families (' + families.length + '): ' + families.map((f) => f.key).join(', '))

function tracePrompt(f) {
  return [
    HAZARDS,
    '',
    SEED,
    '',
    'You are tracing ONE data family end-to-end. Establish, with evidence: (1) produced_by — exact symbols/binaries/scripts that create this data, or NONE if never captured; (2) stores — every location it lands (local path, S3 prefix, in-memory-only), each with durability = one of: none | single-box-local | s3-durable | repo-committed | external-vendor; (3) consumers — everything that reads it in production, research, viewers, or tests (label each); before claiming NONE you MUST grep the whole repo at origin/main including scripts/, tests/, justfile, .github/workflows, *.mjs, *.html; (4) coverage_window — WHEN data flows: continuously / only-while-trading-node-runs / manual-runs-only / one-time-backfill / never; (5) schema_notes — versioning/migration risk; (6) gaps — each with type from: not-captured | captured-not-durable | durable-not-consumed | consumed-not-actionable | not-converted | coverage-window | schema-risk | single-point-of-loss; (7) claims — your load-bearing claims each with command + excerpt; (8) unknowns — anything you could not establish from the repo (e.g. on-box file sizes) with how to check manually.',
    '',
    'FAMILY: ' + f.key + ' — ' + f.name,
    'WHAT: ' + f.what,
    'START FROM THESE POINTERS: ' + JSON.stringify(f.seed_pointers),
  ].join('\n')
}

function verifyPrompt(f, trace) {
  return [
    HAZARDS,
    '',
    'You are an ADVERSARIAL VERIFIER for one data family. The most dangerous errors in this map are FALSE NEGATIVES: "no consumer" claims when a consumer exists, "local-only" claims when rotation/upload exists, "never captured" claims when a writer exists somewhere unexpected. Yesterday a "nothing consumes X" claim in this repo was refuted — assume this tracer made the same class of error until proven otherwise. For every claim in the trace below: reproduce it yourself at origin/main (git grep / git show / gh / bounded aws read-only). Hunt SPECIFICALLY for hidden consumers (grep scripts/, tests/, justfile, workflows, .mjs, .html, python) and hidden durability (rotation, cron, workflow schedules, uploader code). Verdicts: CONFIRMED only if you reproduced it; REFUTED with the contradicting evidence; UNVERIFIABLE with the exact blocker. Never round UNVERIFIABLE up.',
    '',
    'FAMILY: ' + f.key + ' — ' + f.name,
    '',
    'TRACE (JSON):',
    JSON.stringify(trace),
  ].join('\n')
}

log('Tracing ' + families.length + ' families, each pipelined into adversarial verify')
const bundles = await pipeline(
  families,
  (f) => agent(tracePrompt(f), { label: 'trace:' + f.key, phase: 'Trace', model: 'opus', effort: 'medium', schema: TRACE_SCHEMA }),
  (trace, f) => {
    if (!trace) return null
    return agent(verifyPrompt(f, trace), { label: 'verify:' + f.key, phase: 'Verify', model: 'opus', effort: 'high', schema: VERIFY_SCHEMA }).then((v) => ({ family: f, trace: trace, verify: v }))
  }
)
const traced = bundles.filter(Boolean)
log('Traced+verified: ' + traced.length + '/' + families.length + ' families')

const condensed = traced.map((b) => ({
  key: b.family.key,
  stores: (b.trace.stores || []).map((s) => s.location + ' [' + s.durability + ']'),
  consumers: b.trace.consumers,
  coverage: b.trace.coverage_window,
  gaps: (b.trace.gaps || []).map((g) => g.type + ': ' + g.gap),
  refuted: ((b.verify && b.verify.verdicts) || []).filter((v) => v.verdict === 'REFUTED').map((v) => v.claim),
}))

phase('Critique')
const criticResults = await parallel([
  () =>
    agent(
      [
        HAZARDS,
        '',
        SEED,
        '',
        'You are the COVERAGE CRITIC. Below: the raw six-angle sweep outputs and the canonical family list that was traced. Your job: name every data family that is MISSING from the canonical list. Work the checklist: every binary in src/bin and crates/*/src/bin accounted for? every config key naming a path/prefix mapped to a family? every S3 bucket/prefix from the inventory mapped? every scripts/*.py input AND output mapped? logs/tracing? metrics/probe-stack outputs? host-health samples? kill-switch/loss-accumulator state? backtest fixtures and their provenance? CI-published backtest artifacts? bolt-v1 legacy buckets? external vendor feeds (Chainlink streams, Deribit scraper output, venue archives)? on-box operational files? Run your own targeted greps/gh/aws-read-only checks to confirm a suspected missing family actually exists before listing it. Only list families genuinely absent from the canonical list; give each seed_pointers a tracer can start from.',
        '',
        'CANONICAL FAMILIES TRACED: ' + JSON.stringify(families.map((f) => ({ key: f.key, name: f.name, what: f.what }))),
        '',
        'RAW SWEEPS (JSON):',
        sweepsJson,
      ].join('\n'),
      { label: 'critic:coverage', phase: 'Critique', model: 'opus', effort: 'high', schema: CRITIC_SCHEMA }
    ),
  () =>
    agent(
      [
        HAZARDS,
        '',
        'You are the DEPTH CRITIC. Below: the traced-and-verified data map (condensed). Your job: find where this map would MISLEAD a non-technical owner deciding what to build next. For each family: which decision-relevant claim is still unverified or too vague (durability class asserted without evidence? consumer list that skipped workflows? coverage window guessed?)? Which gaps are understated (a "durable" store with no retention policy, a schema with no migration story, a single S3 bucket with no versioning/backup, capture that only runs while trading)? Output weak_spots per family_key, and missing_families ONLY if you personally confirm one exists (with seed_pointers). Run targeted checks yourself where cheap.',
        '',
        'TRACED MAP (condensed JSON):',
        JSON.stringify(condensed),
        '',
        'FULL VERIFY VERDICTS:',
        JSON.stringify(traced.map((b) => ({ key: b.family.key, verdicts: b.verify ? b.verify.verdicts : [], corrections: b.verify ? b.verify.corrections : [] }))),
      ].join('\n'),
      { label: 'critic:depth', phase: 'Critique', model: 'opus', effort: 'high', schema: CRITIC_SCHEMA }
    ),
])
const critics = criticResults.filter(Boolean)

let missing = []
for (const c of critics) missing = missing.concat(c.missing_families || [])
const seen = new Set(families.map((f) => f.key.toLowerCase()))
missing = missing.filter((m) => m && m.name && !seen.has(m.name.toLowerCase()))
if (missing.length > 6) {
  log('Critics found ' + missing.length + ' missing families; supplementing top 6, dropping: ' + missing.slice(6).map((m) => m.name).join(', '))
  missing = missing.slice(0, 6)
} else {
  log('Critics found ' + missing.length + ' missing families to supplement')
}

let supplements = []
if (missing.length > 0) {
  const missFamilies = missing.map((m, i) => ({ key: 'supp-' + (i + 1) + '-' + m.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 40), name: m.name, what: m.why, seed_pointers: m.seed_pointers || [], priority: 1 }))
  const suppBundles = await pipeline(
    missFamilies,
    (f) => agent(tracePrompt(f), { label: 'trace:' + f.key, phase: 'Supplement', model: 'opus', effort: 'medium', schema: TRACE_SCHEMA }),
    (trace, f) => {
      if (!trace) return null
      return agent(verifyPrompt(f, trace), { label: 'verify:' + f.key, phase: 'Supplement', model: 'opus', effort: 'high', schema: VERIFY_SCHEMA }).then((v) => ({ family: f, trace: trace, verify: v }))
    }
  )
  supplements = suppBundles.filter(Boolean)
}

phase('Consolidate')
const allBundles = traced.concat(supplements)
const issueSweep = sweeps.find((s) => s.angle === 'issue-graph')
const consolidated = await agent(
  [
    HAZARDS,
    '',
